/**
 * The emoji catalog: the complete Unicode list, generated and built into the package.
 *
 * There is no network request here, no sprite sheet, no CDN. An emoji is a
 * Unicode glyph that already lives on the writer's machine; what is missing is
 * the Portuguese name to get it there. That name, and the search words, are
 * what this file brings.
 *
 * **Where the data comes from.** `emoji.gen.ts` is generated by
 * `scripts/gerar-emojis.mjs` from files kept in the repo, in
 * `packages/ui/dados/emoji/`: Unicode's `emoji-test.txt` (order, groups; only
 * `fully-qualified` emojis, no skin tone variants) and the CLDR annotations
 * (names and words in pt-PT, pt and en). `ORIGEM.md` in that folder says where
 * each file was downloaded and its checksum. The script never uses the network.
 *
 * **Names.** The name shown, and read by the screen reader, is Portuguese. The
 * hand-written names in `nomes-manuais.txt` win over CLDR, synonyms included.
 * Search also matches the English name and words, because the interface is
 * in English by default.
 *
 * **Loading.** Only `EmojiPicker` imports this file, and it does so with a dynamic
 * `import()` the first time the picker opens, so the catalog stays out of the
 * main bundle.
 *
 * To change a name or add a synonym: edit one line in `nomes-manuais.txt`
 * (`<glyph> <name> | <synonyms>`), then regenerate:
 *
 *     node scripts/gerar-emojis.mjs
 *
 * To move to a newer Unicode version: add the new data files, change the two
 * version constants in the script, regenerate. `emoji.test.ts` fails if the
 * generated file is out of date.
 */

import { EMOJI_CATEGORY_TABS, type EmojiCategoryId } from "./emoji-categorias.js"
import { EMOJI_LINES, EMOJI_TONE_LINES } from "./emoji.gen.js"
import { linguaActual } from "../strings.js"

export interface Emoji {
  /** The glyph. Never normalized: normalizing would break ZWJ sequences. */
  char: string
  /**
   * The name in the interface language: what shows and what the screen reader
   * announces (20/11/2026: it was always Portuguese). A getter, so a language
   * change reaches emojis already built.
   */
  readonly name: string
  /** The Portuguese name. */
  namePt: string
  /** The English name (CLDR). */
  nameEn: string
  /**
   * Name and synonyms, lowercase and without accents, ready to compare.
   * Pre-calculated at startup because search runs on every keystroke.
   */
  haystack: string
}

export interface EmojiCategory {
  /** Also the key for the category separator label in `strings.emoji.categorias`:
   * the label is visible text and lives in the catalog, in both languages. */
  id: EmojiCategoryId
  /** Separator glyph: an emoji from the category itself, which explains itself
   * and does not need nine new icons drawn. */
  symbol: string
  emojis: Emoji[]
}

/**
 * Strip accents and capitals for comparison.
 *
 * Without this, "cafe" would not find "café" and "girassol" would not find
 * "Girassol", in Portuguese accents are the rule, not the exception, and
 * nobody types accents in a search box.
 */
export function fold(text: string): string {
  return (
    text
      .normalize("NFD")
      // \p{M} not a hand-written range: raw combining marks would be invisible to
      // someone reading the file and would not survive a careless copy-paste.
      .replace(/\p{M}/gu, "")
      .toLowerCase()
  )
}

/**
 * Text for comparison: `fold`, then punctuation becomes a single space, so
 * "bandeira: Portugal" is found by "bandeira portugal" and "arco-íris" by
 * "arco iris".
 */
function normalize(text: string): string {
  return fold(text).replace(/[^\p{L}\p{N}]+/gu, " ").trim()
}

/** One line per emoji: `<glyph> <name> | <search words>`. See the generator. */
function parse(lines: readonly string[]): Emoji[] {
  return lines.map((line) => {
    // The glyph runs to the first space. No emoji sequence contains a space, not
    // even those made with ZWJ, so the split is safe.
    const space = line.indexOf(" ")
    const rest = line.slice(space + 1)
    const bar = rest.indexOf(" | ")
    const nomes = bar === -1 ? rest : rest.slice(0, bar)
    const terms = bar === -1 ? "" : rest.slice(bar + 3)
    const til = nomes.indexOf(" ~ ")
    const namePt = til === -1 ? nomes : nomes.slice(0, til)
    const nameEn = til === -1 ? nomes : nomes.slice(til + 3)
    return {
      char: line.slice(0, space),
      namePt,
      nameEn,
      get name() {
        return linguaActual() === "pt" ? namePt : nameEn
      },
      // Both names: a search finds the emoji in either language.
      haystack: normalize([namePt, nameEn === namePt ? "" : nameEn, terms].filter(Boolean).join(" ")),
    }
  })
}

export const CATEGORIES: readonly EmojiCategory[] = EMOJI_CATEGORY_TABS.map((tab) => ({
  ...tab,
  emojis: parse(EMOJI_LINES[tab.id]),
}))

const ALL: readonly Emoji[] = CATEGORIES.flatMap((category) => category.emojis)

/** Variation selector 16: the same emoji is stored with and without it. */
const VS16 = /\uFE0F/g

/** From glyph to its record. Recent ones store only the glyph, the name the
 * screen reader announces comes from here. */
const BY_CHAR = new Map(ALL.map((emoji) => [emoji.char, emoji]))
/** Same, ignoring the variation selector, for a glyph saved by an older catalog
 * or typed by a keyboard that leaves it out. */
const BY_BASE = new Map(ALL.map((emoji) => [emoji.char.replace(VS16, ""), emoji]))

/**
 * The skin tones: base glyph -> the five variants, light to dark, with the same
 * tone on every person in the emoji. Only emojis that take a tone are here.
 */
const TONES = new Map<string, readonly string[]>(
  EMOJI_TONE_LINES.map((line) => {
    const [base = "", ...variants] = line.split(" ")
    return [base, variants]
  }),
)

/** From a toned glyph back to its base record, for the name. */
const BY_TONED = new Map<string, Emoji>()
for (const [base, variants] of TONES) {
  const emoji = BY_CHAR.get(base)
  if (emoji) for (const variant of variants) BY_TONED.set(variant, emoji)
}

export function findEmoji(char: string): Emoji | undefined {
  return BY_CHAR.get(char) ?? BY_BASE.get(char.replace(VS16, "")) ?? BY_TONED.get(char)
}

/** Does this emoji take a skin tone? */
export function takesTone(char: string): boolean {
  return TONES.has(char)
}

/**
 * The glyph in a skin tone. `tone` is 0 (the default yellow) to 5 (dark).
 * An emoji that takes no tone stays as it is.
 */
export function withTone(char: string, tone: number): string {
  if (tone < 1 || tone > 5) return char
  return TONES.get(char)?.[tone - 1] ?? char
}

/**
 * Search by name and words, in Portuguese and English, in layers of relevance.
 *
 * In order: the name starts with the whole word; the whole word is somewhere
 * (so "cat" finds cats before "cato"); the name starts with the text (so "co"
 * finds "coração" before "cachorro-quente"); a word starts with the text; the
 * text is anywhere; and last, for a several-word search that is not a phrase
 * ("portugal bandeira"), everything that has every word. Without these layers
 * the order would be the table's, and the table does not know what you were
 * looking for.
 */
export function searchEmoji(query: string, limit = 96): Emoji[] {
  const needle = normalize(query)
  if (!needle) return []
  const tokens = needle.split(" ")
  const layers: Emoji[][] = [[], [], [], [], [], []]
  for (const emoji of ALL) {
    const hay = emoji.haystack
    let layer = -1
    if (hay === needle || hay.startsWith(`${needle} `)) layer = 0
    else if (hay.includes(` ${needle} `) || hay.endsWith(` ${needle}`)) layer = 1
    else if (hay.startsWith(needle)) layer = 2
    else if (hay.includes(` ${needle}`)) layer = 3
    else if (hay.includes(needle)) layer = 4
    else if (tokens.length > 1 && tokens.every((token) => hay.includes(token))) layer = 5
    if (layer >= 0) layers[layer]?.push(emoji)
  }
  return layers.flat().slice(0, limit)
}
